message:
I'm a freelance designer and I've been teaching myself React by building a small portfolio site for a client. There's a contact form, and it works, but my submit button sometimes sends the message twice and the loading spinner flickers weirdly. Here's what I have:

```jsx
function ContactForm() {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [sent, setSent] = useState(false);

  const handleSubmit = async (e) => {
    setLoading(true);
    await fetch('/api/contact', { method: 'POST', body: JSON.stringify({ name, email, message }) });
    setLoading(false);
    setSent(true);
  };

  return (
    <form onSubmit={handleSubmit}>
      ...inputs...
      <button type="submit">{loading ? <Spinner /> : 'Send'}</button>
    </form>
  );
}
```

Can you review it?
